True def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    lines=[]
    for r in range(h-2):
        for c in range(w-2):
            color=g[r][c]
            if color and all(g[rr][cc]==color for rr in range(r,r+3) for cc in range(c,c+3)):
                lines.append((r+1,c+1,color))
    claims={}
    for r,c,color in lines:
        for rr in range(h): claims.setdefault((rr,c),set()).add(color)
        for cc in range(w): claims.setdefault((r,cc),set()).add(color)
    for (r,c),colors in claims.items():
        g[r][c]=next(iter(colors)) if len(colors)==1 else 0
    return g
